  const {
    attributeFields,
    initializationLines
  } = fragmentLines;
  for (let i = 0; i < attributeFields.length; i++) {
    const [glslType, variableName] = attributeFields[i];
    shaderBuilder.addStructField(structId, glslType, variableName);
  }
  structId = CustomShaderPipelineStage.STRUCT_ID_FRAGMENT_INPUT;
  shaderBuilder.addStruct(structId, CustomShaderPipelineStage.STRUCT_NAME_FRAGMENT_INPUT, ShaderDestination.FRAGMENT);
  shaderBuilder.addStructField(structId, CustomShaderPipelineStage.STRUCT_NAME_ATTRIBUTES, "attributes");
  // Add FeatureIds struct from the Feature ID stage
  shaderBuilder.addStructField(structId, FeatureIdPipelineStage.STRUCT_NAME_FEATURE_IDS, "featureIds");
  // Add Metadata struct from the metadata stage
  shaderBuilder.addStructField(structId, MetadataPipelineStage.STRUCT_NAME_METADATA, "metadata");
  // Add MetadataClass struct from the metadata stage
  shaderBuilder.addStructField(structId, MetadataPipelineStage.STRUCT_NAME_METADATA_CLASS, "metadataClass");
  // Add MetadataStatistics struct from the metadata stage
  shaderBuilder.addStructField(structId, MetadataPipelineStage.STRUCT_NAME_METADATA_STATISTICS, "metadataStatistics");
